def lru_misses(capacity: int, requests: list[int]) -> int:
    misses = 0
    cache = {}
    for request in requests:
        if request in cache:
            # Hit: make the key the most recently used
            cache[request] = cache.pop(request)
        else:
            # Miss: insert the key and evict the least recently used key if necessary
            cache[request] = True
            if len(cache) > capacity:
                cache.popitem(last=False)
            misses += 1
    return misses
