def evaluate(expr: str) -> int:
    # Convert the expression to a postfix expression using the Shunting Yard algorithm
    infix_expr = expr.replace("(", " ( ").replace(")", " ) ")
    postfix_expr = []
    operator_stack = []
    for token in infix_expr.split():
        if token == "(":
            operator_stack.append(token)
        elif token == ")":
            while operator_stack and operator_stack[-1] != "(":
                postfix_expr.append(operator_stack.pop())
            operator_stack.pop()
        else:
            postfix_expr.append(token)
    while operator_stack:
        postfix_expr.append(operator_stack.pop())

    # Evaluate the postfix expression using a stack
    value_stack = []
    for token in postfix_expr:
        if token.isdigit():
            value_stack.append(int(token))
        else:
            right = value_stack.pop()
            left = value_stack.pop()
            if token == "+":
                value_stack.append(left + right)
            elif token == "-":
                value_stack.append(left - right)
            elif token == "*":
                value_stack.append(left * right)
            elif token == "/":
                value_stack.append(left // right)
    return value_stack.pop()
