def knapsack(weights, values, capacity):
    # Create a dictionary to store the maximum value for each weight
    max_values = {w: 0 for w in weights}

    # Fill in the dictionary with the maximum values for each weight
    for i in range(len(weights)):
        for j in range(i, len(weights)):
            if weights[i] + weights[j] <= capacity:
                max_values[weights[i] + weights[j]] = max(max_values[weights[i] + weights[j]], values[i] + values[j])

    # Find the maximum value that can be achieved
    max_value = 0
    for i in range(len(weights)):
        if weights[i] <= capacity:
            max_value = max(max_value, values[i] + max_values[capacity - weights[i]])

    return max_value
```

