def evaluate(expr: str) -> int:
    # Remove any whitespace characters from the expression
    expr = expr.replace(" ", "")

    # Evaluate the expression using a stack data structure
    stack = []
    for char in expr:
        if char.isdigit():
            stack.append(int(char))
        elif char == "+":
            result = stack.pop() + stack.pop()
            stack.append(result)
        elif char == "-":
            result = stack.pop() - stack.pop()
            stack.append(result)
        elif char == "*":
            result = stack.pop() * stack.pop()
            stack.append(result)
        elif char == "/":
            result = stack.pop() // stack.pop()
            stack.append(result)
        elif char == "(":
            stack.append(char)
        elif char == ")":
            top = stack.pop()
            while top != "(":
                result = stack.pop() + top
                stack.append(result)
                top = stack.pop()

    return stack.pop()
