def min_window(s: str, t: str) -> str:
    if not t:
        return ''
    seen = {}
    for c in t:
        seen[c] = seen.get(c, 0) + 1
    left = 0
    right = 0
    min_window_len = len(s) + 1
    min_window_start = -1
    while right < len(s):
        current_char = s[right]
        if current_char in seen:
            if seen[current_char] > 0:
                min_window_len = min(min_window_len, right - left + 1)
                min_window_start = left
            seen[current_char] -= 1
        else:
            seen[current_char] = 0
        right += 1
    return s[min_window_start:min_window_start + min_window_len]
```

