```
def knapsack(weights, values, capacity):
    # Initialize a two-dimensional table to store the results of subproblems
    dp = [[0] * (capacity + 1) for _ in range(len(weights) + 1)]

    # Base case: if the capacity is 0, there is no way to take any items
    for i in range(len(weights) + 1):
        dp[i][0] = 0

    # Initialize the first row of the table
    for i in range(1, len(weights) + 1):
        if weights[i - 1] <= capacity:
            dp[i][weights[i - 1]] = values[i - 1]
        else:
            dp[i][weights[i - 1]] = 0

    # Fill in the rest of the table using the recurrence relation
    for i in range(1, len(weights) + 1):
        for j in range(1, capacity + 1):
            if weights[i - 1] > j:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - weights[i - 1]] + values[i - 1])

    # Return the maximum value in the bottom-right corner of the table
    return dp[-1][-1]
```

