def lru_misses(capacity, requests):
    cache = {}
    misses = 0
    for request in requests:
        if request in cache:
            # Hit: make the request key the most recently used
            cache[request] = cache.pop(request)
        else:
            # Miss: insert the request key and evict the least recently used key if necessary
            cache[request] = True
            if len(cache) > capacity:
                cache.popitem(last=False)
            misses += 1
    return misses
