def lru_misses(capacity: int, requests: list[int]) -> int:
    misses = 0
    cache = {}
    for request in requests:
        if request in cache:
            # Hit: move the key to the end of the cache
            cache[request] = cache.pop(request)
        else:
            # Miss: insert the key and evict the least recently used key
            cache[request] = request
            if len(cache) > capacity:
                # Evict the least recently used key
                cache.pop(list(cache)[0])
            misses += 1
    return misses
