def paths_with_obstacles(grid: list[list[int]]) -> int:
    # Initialize a 2D array to store the number of paths for each cell
    num_paths = [[0] * len(grid[0]) for _ in range(len(grid))]

    # Set the starting cell to 1
    num_paths[0][0] = 1

    # Loop through each row and column of the grid
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            # If the current cell is blocked, set the number of paths to 0
            if grid[i][j] == 1:
                num_paths[i][j] = 0
            # If the current cell is not blocked, add the number of paths from the previous cell
            else:
                if i > 0 and num_paths[i - 1][j] > 0:
                    num_paths[i][j] += num_paths[i - 1][j]
                if j > 0 and num_paths[i][j - 1] > 0:
                    num_paths[i][j] += num_paths[i][j - 1]

    # Return the number of distinct paths from the bottom-right cell
    return num_paths[-1][-1]
