def next_permutation(nums: list[int]) -> list[int]:
    if len(nums) <= 1:
        return nums

    i = len(nums) - 2
    while i >= 0 and nums[i] >= nums[i+1]:
        i -= 1

    if i == -1:
        return sorted(nums)

    j = len(nums) - 1
    while nums[j] <= nums[i]:
        j -= 1

    nums[i], nums[j] = nums[j], nums[i]

    nums[i+1:] = nums[i+1:][::-1]

    return nums
