def min_window(s, t):
    if not t:
        return ''
    seen = {}
    for c in t:
        seen[c] = seen.get(c, 0) + 1
    min_len = float('inf')
    min_window = ''
    for i in range(len(s)):
        c = s[i]
        if c in seen:
            seen[c] -= 1
            if seen[c] == 0:
                del seen[c]
            if not seen:
                min_len = min(min_len, i - len(min_window) + 1)
