def edit_distance(a, b):
    m = len(a) + 1
    n = len(b) + 1
    d = [[0] * (n) for _ in range(m)]

    for i in range(1, m):
        for j in range(1, n):
            if a[i - 1] == b[j - 1]:
                d[i][j] = d[i - 1][j - 1]
            else:
                d[i][j] = min(d[i - 1][j - 1] + 1, d[i - 1][j] + 1, d[i][j - 1] + 1)

    return d[m - 1][n - 1]
```

